mapper.select:
SELECT r.*, u.unit_number, b.name AS building_name, c.name AS community_name FROM residents r LEFT JOIN units u ON r.unit_id = u.id LEFT JOIN buildings b ON u.building_id = b.id LEFT JOIN communities c ON b.community_id = c.id
AND r.unit_id = #{unitId} AND r.status = #{status}
ORDER BY r.id DESC
